38	            let rect = Geometry::Rect(size).filled(fill);
39	            shape::render_shape(&mut canvas, state, &rect);
40	        }
41	    }
42	
43	    let state = state.pre_translate(Point { x: bleed.left, y: bleed.top });
44	
45	    render_frame(&mut canvas, state, &page.frame);
46	
