91	impl CompileConfig {
92	    /// Preprocess a `CompileCommand`, producing a compilation config.
93	    pub fn new(command: &CompileCommand) -> HintedStrResult<Self> {
94	        Self::new_impl(&command.args, None)
95	    }
96	
97	    /// Preprocess a `WatchCommand`, producing a compilation config.
98	    pub fn watching(command: &WatchCommand) -> HintedStrResult<Self> {
99	        Self::new_impl(&command.args, Some(command))
100	    }
101	
102	    /// The shared implementation of [`CompileConfig::new`] and
103	    /// [`CompileConfig::watching`].
104	    fn new_impl(
105	        args: &CompileArgs,
106	        watch: Option<&WatchCommand>,
107	    ) -> HintedStrResult<Self> {
108	        let mut warnings = Vec::new();
109	        let input = args.input.clone();
110	
111	        let output_format = if let Some(specified) = args.format {
112	            specified
113	        } else if let Some(Output::Path(output)) = &args.output {
114	            match output.extension() {
115	                Some(ext) if ext.eq_ignore_ascii_case("pdf") => OutputFormat::Pdf,
116	                Some(ext) if ext.eq_ignore_ascii_case("png") => OutputFormat::Png,
117	                Some(ext) if ext.eq_ignore_ascii_case("svg") => OutputFormat::Svg,
118	                Some(ext) if ext.eq_ignore_ascii_case("html") => OutputFormat::Html,
119	                _ => bail!(
120	                    "could not infer output format for path {}.\n\
121	                     consider providing the format manually with `--format/-f`",
122	                    output.display(),
123	                ),
124	            }
125	        } else {
126	            OutputFormat::Pdf
127	        };
128	
129	        let output = args.output.clone().unwrap_or_else(|| {
130	            let Input::Path(path) = &input else {
131	                panic!("output must be specified when input is from stdin, as guarded by the CLI");
132	            };
133	            Output::Path(path.with_extension(
134	                match output_format {
135	                    OutputFormat::Pdf => "pdf",
136	                    OutputFormat::Png => "png",
137	                    OutputFormat::Svg => "svg",
138	                    OutputFormat::Html => "html",
139	                    OutputFormat::Bundle => "",
140	                },
141	            ))
142	        });
143	
144	        let pages = args.pages.as_ref().map(|export_ranges| {
145	            PageRanges::new(export_ranges.iter().map(|r| r.0.clone()).collect())
146	        });
147	
148	        let tagged = !args.no_pdf_tags && pages.is_none();
149	        if output_format == OutputFormat::Pdf && pages.is_some() && !args.no_pdf_tags {
150	            warnings.push(
151	                HintedString::from("using --pages implies --no-pdf-tags").with_hints([
152	                    "the resulting PDF will be inaccessible".into(),
153	                    "add --no-pdf-tags to silence this warning".into(),
154	                ]),
155	            );
156	        }
157	
158	        if !tagged {
159	            const ACCESSIBLE: &[(PdfStandard, &str)] = &[
160	                (PdfStandard::A_1a, "PDF/A-1a"),
161	                (PdfStandard::A_2a, "PDF/A-2a"),
162	                (PdfStandard::A_3a, "PDF/A-3a"),
163	                (PdfStandard::UA_1, "PDF/UA-1"),
164	            ];
165	
166	            for (standard, name) in ACCESSIBLE {
167	                if args.pdf_standard.contains(standard) {
168	                    if args.no_pdf_tags {
169	                        bail!("cannot disable PDF tags when exporting a {name} document");
170	                    } else {
171	                        bail!(
172	                            "cannot disable PDF tags when exporting a {name} document";
173	                            hint: "using --pages implies --no-pdf-tags";
174	                        );
175	                    }
176	                }
177	            }
178	        }
179	
180	        let pdf_standards = PdfStandards::new(
181	            &args.pdf_standard.iter().copied().map(Into::into).collect::<Vec<_>>(),
182	        )?;
183	
184	        #[cfg(feature = "http-server")]
185	        let server = if let Some(command) = watch
186	            && !command.server.no_serve
187	            && matches!(output_format, OutputFormat::Html | OutputFormat::Bundle)
188	        {
189	            Some(HttpServer::new(
190	                &eco_format!("{input}"),
191	                command.server.port,
192	                !command.server.no_reload,
193	            )?)
194	        } else {
195	            None
196	        };
197	
198	        let mut deps = args.deps.clone();
199	        let mut deps_format = args.deps_format;
200	
201	        if let Some(path) = &args.make_deps
202	            && deps.is_none()
203	        {
204	            deps = Some(Output::Path(path.clone()));
205	            deps_format = DepsFormat::Make;
206	            warnings.push(
207	                "--make-deps is deprecated, use --deps and --deps-format instead".into(),
208	            );
209	        }
210	
211	        match (&output, &deps, watch) {
212	            (Output::Stdout, _, Some(_)) => {
213	                bail!("cannot write document to stdout in watch mode");
214	            }
215	            (_, Some(Output::Stdout), Some(_)) => {
216	                bail!("cannot write dependencies to stdout in watch mode")
217	            }
218	            (Output::Stdout, Some(Output::Stdout), _) => {
219	                bail!("cannot write both output and dependencies to stdout")
220	            }
221	            _ => {}
222	        }
223	
224	        Ok(Self {
225	            warnings,
226	            watching: watch.is_some(),
227	            input,
228	            output,
229	            output_format,
230	            pretty: args.pretty,
231	            pages,
232	            pdf_standards,
233	            tagged,
234	            creation_timestamp: args
235	                .world
236	                .creation_timestamp
237	                .map(|time| {
238	                    chrono::DateTime::from_timestamp(time, 0)
239	                        .ok_or("creation timestamp is out of range")
240	                })
241	                .transpose()?,
242	            ppi: args.ppi,
243	            diagnostic_format: args.process.diagnostic_format,
244	            open: args.open.clone(),
245	            export_cache: ExportCache::new(),
246	            deps,
247	            deps_format,
248	            #[cfg(feature = "http-server")]
249	            server,
250	        })
251	    }
252	}
