673	/// Opens the output if desired.
674	fn open_output(config: &mut CompileConfig) -> StrResult<()> {
675	    let Some(viewer) = config.open.take() else { return Ok(()) };
676	
677	    #[cfg(feature = "http-server")]
678	    if let Some(server) = &config.server {
679	        let url = format!("http://{}", server.addr());
680	        return open_path(OsStr::new(&url), viewer.as_deref());
681	    }
682	
683	    // Can't open stdout.
684	    let Output::Path(path) = &config.output else { return Ok(()) };
685	
686	    // Some resource openers require the path to be canonicalized.
687	    let path = path
688	        .canonicalize()
689	        .map_err(|err| eco_format!("failed to canonicalize path ({err})"))?;
690	
691	    open_path(path.as_os_str(), viewer.as_deref())
692	}
693	
694	/// Opens the given file using:
695	///
696	/// - The default file viewer if `app` is `None`.
697	/// - The given viewer provided by `app` if it is `Some`.
698	fn open_path(path: &OsStr, viewer: Option<&str>) -> StrResult<()> {
699	    if let Some(viewer) = viewer {
700	        open::with_detached(path, viewer)
701	            .map_err(|err| eco_format!("failed to open file with {viewer} ({err})"))
702	    } else {
703	        open::that_detached(path).map_err(|err| {
704	            let openers = open::commands(path)
705	                .iter()
